#!/usr/bin/env bash
# run.sh — menu-driven launcher for this project's tutorials.
#
# Generated by /tutorial. Buckets are the numbered *.sh files beside this one;
# adding a file adds a menu entry, so the menu never needs hand-editing.
#
#   ./tutorials/run.sh          menu
#   ./tutorials/run.sh 2        run bucket 2 directly
#   ./tutorials/run.sh all      run every bucket in order
#   ./tutorials/run.sh --auto 2 run bucket 2 unattended (no Enter prompts)

set -uo pipefail
TUT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if [ -r /dev/tty ] && { : >/dev/tty; } 2>/dev/null; then TUT_TTY=/dev/tty; else TUT_TTY=/dev/stdin; fi

if [ -t 1 ] && [ -z "${NO_COLOR:-}" ]; then
    B=$'\033[1;36m'; D=$'\033[2m'; Y=$'\033[1;33m'; O=$'\033[0m'
else
    B=""; D=""; Y=""; O=""
fi

# Each bucket declares its own title/duration in two comment lines:
#   # TUTORIAL-TITLE: Walking the CLI
#   # TUTORIAL-MINUTES: 7
bucket_meta() {
    local f="$1" key="$2"
    sed -n "s/^# TUTORIAL-${key}: //p" "$f" | head -1
}

list_buckets() {
    find "$TUT_DIR" -maxdepth 1 -name '[0-9][0-9]-*.sh' -type f | sort
}

show_menu() {
    printf '\n%s╭─ Tutorials%s\n' "$B" "$O"
    local i=0 f title mins
    while IFS= read -r f; do
        [ -z "$f" ] && continue
        i=$((i + 1))
        title=$(bucket_meta "$f" TITLE); mins=$(bucket_meta "$f" MINUTES)
        printf '%s│%s  %s%2d%s  %-46s %s%s min%s\n' \
            "$B" "$O" "$Y" "$i" "$O" "${title:-$(basename "$f")}" "$D" "${mins:-?}" "$O"
    done <<< "$(list_buckets)"
    if [ "$i" -eq 0 ]; then
        printf '%s│%s  (no tutorials yet — run /tutorial to create one)\n' "$B" "$O"
    fi
    printf '%s│%s\n' "$B" "$O"
    printf '%s│%s  %sa%s   run everything in order\n' "$B" "$O" "$Y" "$O"
    printf '%s│%s  %sq%s   quit\n' "$B" "$O" "$Y" "$O"
    printf '%s╰──────────────────────────────────────────────────────%s\n\n' "$B" "$O"
}

run_bucket() {
    local f="$1"
    [ -f "$f" ] || { echo "no such tutorial: $f" >&2; return 1; }
    bash "$f"
}

run_nth() {
    local n="$1" f
    f=$(list_buckets | sed -n "${n}p")
    [ -z "$f" ] && { echo "no tutorial #$n" >&2; return 1; }
    run_bucket "$f"
}

# Runs every bucket even if one fails, then reports whether any did.
run_all() {
    local f rc=0
    while IFS= read -r f; do
        [ -z "$f" ] && continue
        run_bucket "$f" || rc=1
    done <<< "$(list_buckets)"
    return $rc
}

# ── Args ────────────────────────────────────────────────────────────────────
if [ "${1:-}" = "--auto" ]; then export TUT_AUTO=1; shift; fi

case "${1:-}" in
    "")    ;;                                  # fall through to the menu
    all|a) run_all; exit $? ;;
    *[!0-9]*) run_bucket "$TUT_DIR/$1"; exit $? ;;
    *)     run_nth "$1"; exit $? ;;
esac

while true; do
    show_menu
    printf 'choose: '
    IFS= read -r choice <"$TUT_TTY" || exit 0
    case "$choice" in
        q|Q|"") exit 0 ;;
        a|A)    run_all ;;
        *[!0-9]*) echo "not a choice: $choice" ;;
        *)      run_nth "$choice" || true ;;
    esac
done
